// s34 — 祈年殿平面图. A measured-drawing style plan on white drafting paper:
// the shared arc is the heavy ink circle of the hall's round base (台明外圆). Inside it sit the eave-column ring
// (檐柱圈) and the hypostyle ring (金柱圈) with their columns at 30° steps on shared radial axes, the bay axes
// (点划线), and a net of regulating chords (圆周等分作图线) with a red pair and a blue pair picked out.
// NOTE: ring radii are schematic (no reliable survey figures exist in the research file) — they are generated by the
// chord construction itself, so every column sits on a node of the net. No numbers, no lettering.
import * as L from '../lib/core.js';

const { W, H } = L;
const PAD = 100;   // the move is tiny (zoom ±1.5 %, rot ±0.002) so a small margin is plenty
const INK = '#1a1a1a', RED = '#d23a2a', BLUE = '#2a6fb8', PAPER = '#f4f2ec', LEAD = '#3a3a40';
let S = null;

// ───────── small drafting helpers ─────────
function line(g, p, q, o = {}) {
  const { w = 2, color = INK, alpha = 1, dash = null, over = 0, overEnd = 0 } = o;
  const dx = q.x - p.x, dy = q.y - p.y, len = Math.hypot(dx, dy) || 1, ux = dx / len, uy = dy / len;
  g.save();
  g.strokeStyle = color; g.globalAlpha *= alpha; g.lineWidth = w; g.lineCap = 'butt';
  if (dash) g.setLineDash(dash);
  g.beginPath(); g.moveTo(p.x - ux * over, p.y - uy * over); g.lineTo(q.x + ux * overEnd, q.y + uy * overEnd); g.stroke();
  g.restore();
}
function ring(g, a, dr, o = {}, t0, t1) {
  const { w = 1.5, color = INK, alpha = 1, dash = null } = o;
  g.save();
  g.strokeStyle = color; g.globalAlpha *= alpha; g.lineWidth = w; g.lineCap = 'butt';
  if (dash) g.setLineDash(dash);
  a.stroke(g, dr, t0, t1);
  g.restore();
}
/** filled arrowhead with its tip at (x,y) pointing along ang */
function arrow(g, x, y, ang, len = 17, wd = 5.2, color = INK) {
  g.save(); g.translate(x, y); g.rotate(ang); g.fillStyle = color;
  g.beginPath(); g.moveTo(0, 0); g.lineTo(-len, -wd); g.lineTo(-len * 0.78, 0); g.lineTo(-len, wd); g.closePath(); g.fill();
  g.restore();
}
/** the short 45° slash that ends an architectural dimension line; ang = direction of the dimension line */
function slash(g, x, y, ang, len = 20, w = 3.2) {
  g.save(); g.translate(x, y); g.rotate(ang - Math.PI / 4);
  g.strokeStyle = INK; g.lineWidth = w; g.lineCap = 'butt';
  g.beginPath(); g.moveTo(-len / 2, 0); g.lineTo(len / 2, 0); g.stroke();
  g.restore();
}
/** random-alpha tile used to "bite" strokes with paper tooth (destination-out) */
function toothTile(seed, size, density, scale = 1) {
  const n = Math.round(size / scale);
  const c = L.makeCanvas(n, n); const g = c.getContext('2d');
  const img = new ImageData(n, n); const d = img.data; const r = L.rng(seed);
  for (let i = 0; i < d.length; i += 4) { d[i + 3] = r() < density ? 255 * Math.pow(r(), 0.6) : 0; }
  g.putImageData(img, 0, 0);
  if (scale === 1) return c;
  const out = L.makeCanvas(size, size); const og = out.getContext('2d');
  og.imageSmoothingEnabled = true; og.drawImage(c, 0, 0, size, size);
  return out;
}
function bite(layer, tile, alpha) {
  const g = layer.getContext('2d');
  g.save(); g.setTransform(1, 0, 0, 1, 0, 0);
  g.globalCompositeOperation = 'destination-out'; g.globalAlpha = alpha;
  g.fillStyle = g.createPattern(tile, 'repeat'); g.fillRect(0, 0, layer.width, layer.height);
  g.restore();
}

function build(env) {
  const a = env.arc, R = a.R;
  const LW = W + PAD * 2, LH = H + PAD * 2;
  const s = a.span(PAD + 140);
  const rad = L.deg;
  const P = (d, dr = 0) => a.pt(rad(d), dr);
  const C = { x: a.cx, y: a.cy };
  // concentric circles produced by the 24-point chord net (schematic proportions, not survey sizes)
  const dI = R * Math.cos(rad(15)) - R;                       // incircle of the 12-gon
  const dE = (R * Math.cos(rad(30))) / Math.cos(rad(15)) - R; // 檐柱圈 eave-column ring
  const dM = R * Math.cos(rad(30)) - R;                       // dashed overhead line
  const dG = (R * Math.cos(rad(45))) / Math.cos(rad(30)) - R; // 金柱圈 hypostyle ring
  const dD = -150;                                            // dimension arc
  const rE = 36, rG = 46;                                     // column radii: inner ring thicker than outer
  const AXIS = [46, 9, 6, 9];                                 // 点划线
  const chord = (g, da, db, o) => line(g, P(da), P(db), o);

  // chords drawn in ink: [from°, to°, weight]
  const CH = [
    [0, 60, 2.8], [0, -60, 2.8], [0, 120, 2.2], [0, -120, 2.2],
    [-15, 45, 2.8], [15, -45, 2.8], [-15, 75, 2.8], [15, -75, 2.8], [-15, 105, 2.8], [-15, 135, 2.2], [15, -135, 2.2],
    [15, 45, 2.0], [-15, -45, 2.0], [15, 75, 2.0], [-15, -75, 2.0], [15, 105, 2.0], [-15, -105, 2.0],
    [-30, 60, 2.2], [30, -60, 2.2], [-30, 90, 2.0], [30, -90, 2.0],
  ];
  // chords left in pencil only
  const PC = [[-15, 15], [-30, 30], [-15, -165], [15, 165], [0, 30], [0, -30], [0, 150], [0, -150], [-15, -135], [15, 135]];

  // ───────── 1. pencil under-drawing ─────────
  const pencil = L.makeLayer(PAD, (g) => {
    const r = L.rng('s34pencil');
    // soft graphite shading just inside the base edge → the rim reads as a raised kerb
    g.save(); a.clipBelow(g, -40);
    g.fillStyle = L.radial(g, C.x, C.y, R - 130, R - 40, [[0, L.rgba(LEAD, 0)], [1, L.rgba(LEAD, 0.17)]]);
    g.fillRect(-PAD, -PAD, LW, LH);
    g.restore();
    // 45° hatching on the kerb stones
    g.save(); a.clipBand(g, -12, -40, -s, s);
    g.strokeStyle = LEAD; g.globalAlpha = 0.55; g.lineWidth = 1.3;
    g.beginPath();
    for (let x = -PAD - LH; x < W + PAD; x += 7) { g.moveTo(x, H + PAD); g.lineTo(x + LH, -PAD); }
    g.stroke();
    g.restore();
    // square paving of the base (方砖), sketched in on the two side bays only — the middle bay is left clear
    {
      const courses = [-40, -89, -138, -188, dE + 11], step = rad(1.25), t0 = rad(15), t1 = s;
      for (const sg of [-1, 1]) {
        for (let c = 0; c < 4; c++) {
          if (c > 0) ring(g, a, courses[c], { w: 1.2, color: LEAD, alpha: 0.42 }, sg > 0 ? t0 : -t1, sg > 0 ? t1 : -t0);
          for (let t = t0 + step * (c % 2 ? 1 : 0.5); t < t1; t += step) line(g, a.pt(sg * t, courses[c]), a.pt(sg * t, courses[c + 1]), { w: 1.15, color: LEAD, alpha: 0.4 });
        }
      }
    }
    // trial circles from the compass
    ring(g, a, dI, { w: 1.6, color: LEAD, alpha: 0.55 });
    ring(g, a, dI + 2.2, { w: 1.0, color: LEAD, alpha: 0.2 }, -0.3, 0.12);
    ring(g, a, -118, { w: 2.0, color: LEAD, alpha: 0.11 }, -0.36, -0.02);   // rubbed-out arc
    ring(g, a, dG - 34, { w: 1.2, color: LEAD, alpha: 0.3 });
    ring(g, a, dM - 2, { w: 1.1, color: LEAD, alpha: 0.28 });
    // radial bisectors
    for (const d of [-22.5, -7.5, 7.5, 22.5]) line(g, P(d, 14), C, { w: 1.5, color: LEAD, alpha: 0.42 });
    // pencil-only chords
    for (const [da, db] of PC) chord(g, da, db, { w: 1.5, color: LEAD, alpha: 0.42, over: Math.abs(da) === 15 ? r.range(8, 26) : 0 });
    // faint guide lines under every inked chord, overshooting past the circle at the two side stations
    for (const [da, db] of CH.concat([[15, -105]])) {
      const p = P(da), q = P(db);
      const o = r.range(-0.9, 0.9);
      const nx = -(q.y - p.y), ny = q.x - p.x, m = Math.hypot(nx, ny);
      const pp = { x: p.x + (nx / m) * o, y: p.y + (ny / m) * o }, qq = { x: q.x + (nx / m) * o, y: q.y + (ny / m) * o };
      line(g, pp, qq, { w: 1.3, color: LEAD, alpha: 0.34, over: Math.abs(da) === 15 ? r.range(8, 30) : 0 });
    }
    // little compass strikes where the bisectors were found (kept away from the text zone)
    for (const d of [-22.5, 22.5]) {
      const c1 = P(d - 7.5), c2 = P(d + 7.5), rr = R * rad(7.5) * 1.12;
      const q = P(d), a1 = Math.atan2(q.y - c1.y, q.x - c1.x), a2 = Math.atan2(q.y - c2.y, q.x - c2.x);
      g.save(); g.strokeStyle = LEAD; g.globalAlpha = 0.4; g.lineWidth = 1.2;
      g.beginPath(); g.arc(c1.x, c1.y, rr, a1 - 0.5, a1 - 0.2); g.stroke();
      g.beginPath(); g.arc(c2.x, c2.y, rr, a2 + 0.2, a2 + 0.5); g.stroke();
      g.restore();
    }
  });
  bite(pencil, toothTile('s34t2', 256, 0.6, 2), 0.6);
  bite(pencil, toothTile('s34t1', 256, 0.5, 1), 0.35);

  // ───────── 2. red / blue emphasis lines ─────────
  const colour = L.makeLayer(PAD, (g) => {
    const mk = (p, q, col, w, over = 3) => {
      line(g, p, q, { w, color: col, alpha: 0.88, over });
      line(g, p, q, { w: w * 0.5, color: col, alpha: 0.6, over });
    };
    mk(P(0), P(90), RED, 7.5); mk(P(0), P(-90), RED, 7.5);     // 方圆: the inscribed square, struck from the crest
    mk(P(15), P(-105), BLUE, 6.6, 5);                           // its partner from the right-hand station
    mk(P(15, 44), C, BLUE, 4.8, 0);                             // one column axis picked out in blue
    // red rings on the two nodes of the central axis
    g.strokeStyle = RED; g.globalAlpha = 0.88; g.lineWidth = 3;
    for (const dr of [dE, dG]) { const p = P(0, dr); g.beginPath(); g.arc(p.x, p.y, 13, 0, L.TAU); g.stroke(); }
    g.globalAlpha = 1;
  });
  bite(colour, toothTile('s34t3', 256, 0.5, 2), 0.3);

  // ───────── 3. ink ─────────
  const ink = L.makeLayer(PAD, (g) => {
    const r = L.rng('s34ink');
    // the base edge = THE arc (heavy line), with the kerb course just inside it
    ring(g, a, -1.5, { w: 8 });
    ring(g, a, -13, { w: 1.8 });
    ring(g, a, -40, { w: 2.2 });
    a.along({ spacing: 104, dr: -13, t0: -s, t1: s }, (q) => a.at(g, q.theta, -13, () => { g.fillStyle = INK; g.fillRect(-0.8, 0, 1.6, 27); }));
    // division ticks on the circle
    for (let k = -4; k <= 4; k++) {
      const d = k * 7.5, long = k % 2 === 0;
      line(g, P(d, k === 0 ? 4 : long ? 9 : 6), P(d, long ? -12 : -8), { w: long ? 2.2 : 1.6 });
    }
    // dimension arc with slashes at the column axes
    ring(g, a, dD, { w: 1.5 });
    for (let k = -3; k <= 2; k++) { const t = rad(15 + 30 * k), p = a.pt(t, dD); slash(g, p.x, p.y, t); }
    // eave-column ring: axis + door/window band between the columns
    ring(g, a, dE, { w: 1.5, dash: [34, 7, 4, 7] });
    const gapE = (rE * 1.42 + 1) / (R + dE);
    for (let k = -3; k <= 2; k++) {
      const t0 = rad(15 + 30 * k) + gapE, t1 = rad(45 + 30 * k) - gapE;
      for (const [o, w] of [[11, 3.0], [3.8, 1.3], [-3.8, 1.3], [-11, 3.0]]) ring(g, a, dE + o, { w }, t0, t1);
    }
    // overhead line (dashed) and hypostyle ring (axis + dashed ring-beam)
    ring(g, a, dM, { w: 2.0, dash: [18, 10] });
    ring(g, a, dG, { w: 1.5, dash: [34, 7, 4, 7] });
    const gapG = (rG * 1.42 + 1) / (R + dG);
    for (let k = -3; k <= 2; k++) {
      const t0 = rad(15 + 30 * k) + gapG, t1 = rad(45 + 30 * k) - gapG;
      ring(g, a, dG + 9, { w: 1.8, dash: [13, 8] }, t0, t1);
      ring(g, a, dG - 9, { w: 1.8, dash: [13, 8] }, t0, t1);
    }
    // bay axes (点划线): the central axis runs between two columns; the left column axis (the right one is blue)
    line(g, P(0, -1), C, { w: 2.0, dash: AXIS });
    line(g, P(-15, 46), C, { w: 2.0, dash: AXIS });
    // regulating chords, each started from a small blob of ink at its station
    for (const [da, db, w] of CH) {
      chord(g, da, db, { w, alpha: 0.97, over: da === 0 ? 0 : r.range(2, 6) });
      if (Math.abs(da) <= 15) { const p = P(da); g.fillStyle = INK; g.beginPath(); g.arc(p.x, p.y, r.range(1.2, 2.1), 0, L.TAU); g.fill(); }
    }
    // columns: plinth square, column-base ring, solid shaft with a scribed cross
    const column = (d, dr, rr) => a.at(g, rad(d), dr, () => {
      const q = rr * 1.42;
      g.strokeStyle = INK; g.lineWidth = 2.2; g.strokeRect(-q, -q, q * 2, q * 2);
      g.lineWidth = 1.5; g.beginPath(); g.arc(0, 0, rr * 1.2, 0, L.TAU); g.stroke();
      g.fillStyle = INK; g.beginPath(); g.arc(0, 0, rr, 0, L.TAU); g.fill();
      g.globalCompositeOperation = 'destination-out';
      g.lineWidth = 2.2;
      g.beginPath(); g.moveTo(-rr * 0.52, 0); g.lineTo(rr * 0.52, 0); g.moveTo(0, -rr * 0.52); g.lineTo(0, rr * 0.52); g.stroke();
      g.globalCompositeOperation = 'source-over';
    });
    for (let k = -2; k <= 1; k++) { column(15 + 30 * k, dE, rE); column(15 + 30 * k, dG, rG); }
    // nodes on the central axis
    for (const dr of [dE, dG]) { const p = P(0, dr); g.fillStyle = INK; g.beginPath(); g.arc(p.x, p.y, 4, 0, L.TAU); g.fill(); }
    // small cross marks where the bisectors meet the trial circle
    for (const d of [-7.5, 7.5]) {
      const p = P(d, dI);
      g.strokeStyle = INK; g.lineWidth = 1.8;
      g.beginPath(); g.moveTo(p.x - 9, p.y); g.lineTo(p.x + 9, p.y); g.moveTo(p.x, p.y - 9); g.lineTo(p.x, p.y + 9); g.stroke();
    }
    // station points on the circle
    for (const d of [-15, 0, 15]) { const p = P(d); g.fillStyle = INK; g.beginPath(); g.arc(p.x, p.y, 4.4, 0, L.TAU); g.fill(); }
    // right-angle mark + protractor arc under the crest
    const c0 = P(0), q = 30 * Math.SQRT1_2;
    g.strokeStyle = INK; g.lineWidth = 1.9;
    g.beginPath(); g.moveTo(c0.x + q, c0.y + q); g.lineTo(c0.x, c0.y + 2 * q); g.lineTo(c0.x - q, c0.y + q); g.stroke();
    g.lineWidth = 1.6; g.beginPath(); g.arc(c0.x, c0.y, 122, rad(30), rad(150)); g.stroke();
    arrow(g, c0.x + 122 * Math.cos(rad(30)), c0.y + 122 * Math.sin(rad(30)), rad(30) - Math.PI / 2);
    arrow(g, c0.x + 122 * Math.cos(rad(150)), c0.y + 122 * Math.sin(rad(150)), rad(150) + Math.PI / 2);
    // angle arcs at the side stations
    const f1 = P(-15), f2 = P(15);
    const angArc = (c, rr, d0, d1) => {
      g.strokeStyle = INK; g.lineWidth = 1.6; g.beginPath(); g.arc(c.x, c.y, rr, rad(d0), rad(d1)); g.stroke();
      arrow(g, c.x + rr * Math.cos(rad(d0)), c.y + rr * Math.sin(rad(d0)), rad(d0) - Math.PI / 2, 15, 4.6);
      arrow(g, c.x + rr * Math.cos(rad(d1)), c.y + rr * Math.sin(rad(d1)), rad(d1) + Math.PI / 2, 15, 4.6);
    };
    angArc(f1, 156, 15, 75); angArc(f1, 96, 45, 75);
    angArc(f2, 118, 105, 135);
    // radial dimension chain on the right
    {
      const d = 20.5, p0 = P(d, 16), p1 = P(d, dG - 16), ang = Math.atan2(C.y - p0.y, C.x - p0.x);
      line(g, p0, p1, { w: 1.5 });
      for (const dr of [0, dE, dG]) { const p = P(d, dr); slash(g, p.x, p.y, ang); }
    }
  });
  // ink is never perfectly even: thin it a touch in patches and let the paper tooth nibble the edges
  {
    const g = ink.getContext('2d');
    g.save(); g.setTransform(1, 0, 0, 1, 0, 0); g.globalCompositeOperation = 'destination-out';
    g.drawImage(L.noiseTex(LW, LH, { seed: 's34inkden', scale: 46, octaves: 3, res: 0.25, contrast: 1.7, ramp: [[0, 'rgba(0,0,0,0)'], [0.5, 'rgba(0,0,0,0)'], [1, 'rgba(0,0,0,0.16)']] }), 0, 0);
    g.restore();
  }
  bite(ink, toothTile('s34t4', 256, 0.35, 1), 0.2);

  // ───────── 4. the sheet: paper + everything drawn on it ─────────
  const paper = L.paperTex(LW, LH, { base: '#f7f5f0', seed: 34, tone: '#98927f', fiber: 0.3, stain: 0.14, grain: 0.14 });
  const toothBump = L.bumpLight(L.noiseTex(512, 512, { seed: 's34tooth', scale: 3.2, octaves: 2, res: 1, contrast: 1.6 }), { strength: 1.8, res: 1 });
  let sheet = L.makeLayer(PAD, (g) => {
    g.drawImage(paper, -PAD, -PAD);
    // inside the circle the paper has been worked: a breath of graphite haze + smudges
    g.save(); a.clipBelow(g, -2);
    g.fillStyle = 'rgba(96,92,84,0.04)'; g.fillRect(-PAD, -PAD, LW, LH);
    g.globalCompositeOperation = 'multiply';
    g.drawImage(L.noiseTex(LW, LH, { seed: 's34haze', scale: 420, octaves: 3, res: 0.15, contrast: 1.3, ramp: [[0, '#ffffff'], [0.45, '#ffffff'], [1, '#eeedea']] }), -PAD, -PAD);
    g.restore();
    // paper tooth catching the raking light
    g.save(); g.globalCompositeOperation = 'soft-light'; g.globalAlpha = 0.42;
    g.fillStyle = g.createPattern(toothBump, 'repeat'); g.fillRect(-PAD, -PAD, LW, LH);
    g.restore();
    L.speckle(g, { seed: 's34sp', count: 200, x: -PAD, y: -PAD, w: LW, h: LH, rMin: 0.4, rMax: 1.3, colors: ['#6a655a', '#8a8478'], alpha: [0.08, 0.3] });
    g.globalCompositeOperation = 'multiply';
    g.drawImage(pencil, -PAD, -PAD);
    g.drawImage(colour, -PAD, -PAD);
    g.drawImage(ink, -PAD, -PAD);
  });
  sheet = L.blurred(sheet, 0.4);

  // ───────── 5. paper curl, window light and lens fall-off, baked into the sheet ─────────
  {
    const g = sheet.getContext('2d');
    g.save(); g.setTransform(1, 0, 0, 1, 0, 0);
    // the sheet has been kept rolled and does not lie perfectly flat: broad, soft bands of light and shade
    g.save(); g.globalCompositeOperation = 'multiply';
    g.fillStyle = L.linear(g, PAD - 200, 0, PAD + W + 200, 260, [[0, '#f3f1ec'], [0.14, '#ffffff'], [0.3, '#f6f4ef'], [0.47, '#ffffff'], [0.66, '#f4f2ed'], [0.8, '#fefdfb'], [1, '#f1efe9']]);
    g.fillRect(0, 0, LW, LH);
    g.restore();
    // the lens is focused on the crest; the picture softens toward the near edge and the corners
    const ox = a.cx + PAD, oy = a.crestY + PAD + 70;
    const defocus = (px, r0, r1) => {
      const b = L.blurred(sheet, px), bg = b.getContext('2d');
      bg.save(); bg.globalCompositeOperation = 'destination-in';
      bg.translate(ox, oy); bg.scale(2.1, 1);
      bg.fillStyle = L.radial(bg, 0, 0, r0, r1, [[0, 'rgba(0,0,0,0)'], [1, 'rgba(0,0,0,1)']]);
      bg.fillRect(-LW, -LH, LW * 2, LH * 2);
      bg.restore();
      return b;
    };
    const soft1 = defocus(1.3, 250, 520), soft2 = defocus(3.2, 430, 820);
    g.drawImage(soft1, 0, 0); g.drawImage(soft2, 0, 0);
    // window light from the upper left, falling off toward the lower right
    g.globalCompositeOperation = 'multiply';
    g.fillStyle = L.linear(g, PAD, PAD, PAD + W, PAD + H, [[0, '#ffffff'], [0.5, '#fbfaf7'], [1, '#e7e4db']]);
    g.fillRect(0, 0, LW, LH);
    g.fillStyle = L.radial(g, PAD + W + 260, PAD + H + 300, 100, 1000, [[0, 'rgba(60,56,50,0.22)'], [1, 'rgba(60,56,50,0)']]);
    g.fillRect(0, 0, LW, LH);
    g.restore();
  }
  return { sheet };
}

export default {
  name: '祈年殿平面图',
  tone: 'dark',
  init(env) { S = build(env); },
  draw(ctx, env, p) {
    // slow push-in centred on the crest + a hair of rotation about the plan's centre
    const zoom = L.lerp(0.99, 1.016, p), rot = L.lerp(-0.002, 0.002, p);
    ctx.fillStyle = PAPER; ctx.fillRect(0, 0, W, H);
    L.blit(ctx, env, S.sheet, { rot, zoom });
  },
};
